/**
 * @distilled.cloud/npm -- npm registry API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from npm's OpenAPI documents, mirrored at
 * `specs/spec-mirror-npm/specs/api`. Everything else in this folder is
 * hand-written.
 *
 * One module per document: `access`, `audit`, `oidc`, `org`,
 * `packageVersionStatus`, `publish`, `search`, `stage`, `team`, `token` and
 * `trust`.
 *
 * @example
 * ```ts
 * import * as Npm from "@distilled.cloud/npm";
 *
 * const { objects } = yield* Npm.search.searchPackages({ text: "effect", size: 5 });
 * const { public: isPublic } = yield* Npm.access.getPackageVisibility({
 *   escapedPackageName: "@npmcli/arborist",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { NpmProtocol, type NpmOpError, type NpmOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
